/**
 * The team hub's Coaching Profile & Tendencies section
 * (src/lib/team/coaching*.ts).
 *
 * Asserts the build spec's acceptance checklist on the served HTML. The Bills
 * are the reference club; since 2026-10-01 their entry is generated by
 * buildCoaching.mjs like the other 31 (the hand-written original is gone), so
 * the pinned copy below is the generated copy. The four feed-backed tendency
 * rows are checked against the committed usage file, since that is where
 * their live numbers come from.
 */

import test, { before, after, describe } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { JSDOM } from "jsdom";
import { startServer, APP_DIR } from "./helpers/server.mjs";
import { startUpstreamReplay } from "./helpers/upstream-replay.mjs";

let server;
let replay;

const coaching = JSON.parse(
  fs.readFileSync(path.join(APP_DIR, "data", "team", "coaching_2026.json"), "utf8"),
);
const usage = JSON.parse(
  fs.readFileSync(path.join(APP_DIR, "data", "team", "usage_2026.json"), "utf8"),
);

before(async () => {
  replay = await startUpstreamReplay();
  server = await startServer(replay.env);
});

after(async () => {
  await server?.stop();
  await replay?.stop();
});

async function page(pathname) {
  const res = await fetch(`${server.origin}${pathname}`);
  assert.equal(res.status, 200, pathname);
  const body = await res.text();
  return { body, doc: new JSDOM(body).window.document };
}

describe("placement", () => {
  test("the tab sits between Usage and Stats and links to the section's own address", async () => {
    const { doc } = await page("/team/buffalo-bills/");
    const ids = [...doc.querySelectorAll(".sct-nav-link")].map((a) => a.getAttribute("data-sct-panel-id"));
    assert.deepEqual(ids.slice(0, 4), ["outlook", "usage", "coaching", "stats"]);
    const tabs = [...doc.querySelectorAll(".sct-nav-link")].map((a) => a.textContent);
    assert.deepEqual(tabs.slice(0, 4), ["Outlook", "Usage", "Coaching", "Stats"]);
    // Its own address since mak's coaching brief (2026-11-05): the hub prints
    // no coaching panel, and the tab is a link to /coaching/ (ownsAddress).
    assert.equal(doc.querySelector("#coaching-tab").getAttribute("href"), "/team/buffalo-bills/coaching/");
    assert.equal(doc.getElementById("coaching"), null, "the coaching panel is not printed on the hub");
  });

  test("/coaching/ is a section page: that panel alone, its own H1 phrase, title and description", async () => {
    const res = await fetch(`${server.origin}/team/buffalo-bills/coaching/`);
    assert.equal(res.status, 200);
    const doc = new JSDOM(await res.text()).window.document;
    assert.deepEqual([...doc.querySelectorAll("[data-sct-panel]")].map((s) => s.id), ["coaching"]);
    assert.equal(doc.title, "Buffalo Bills Offensive Coordinator & Scheme 2026");
    assert.equal(
      doc.querySelector('meta[name="description"]').getAttribute("content"),
      "Explore the 2026 Buffalo Bills offense: who calls the plays, pass rate, formations, offensive tendencies, and coaching history.",
    );
    assert.equal(doc.querySelector('link[rel="canonical"]')?.getAttribute("href")?.endsWith("/coaching/"), true);
    const embed = await page("/embed/team/buffalo-bills?section=coaching&h1=1");
    assert.equal(embed.doc.querySelector("h1").textContent, "Buffalo Bills Offensive Coordinator & Scheme (2026)");
  });

  test("a generated club renders the panel and the tab", async () => {
    const { doc } = await page("/team/new-england-patriots/coaching/");
    assert.ok(doc.querySelector("#coaching"), "coaching panel renders");
    assert.ok(doc.querySelector("#coaching .sct-co"), "coaching section inside it");
  });
});

describe("the page since mak kept the premium designs (2026-11-05)", () => {
  test("premium top block, premium tendencies dashboard, then career and fantasy; the originals are unmounted", async () => {
    const { doc } = await page("/team/buffalo-bills/coaching/");
    const panel = doc.querySelector("#coaching");
    const cp = panel.querySelector("#coaching-premium.sct-cp");
    const cpt = panel.querySelector("#coaching-premium-tendencies.sct-cp.sct-cpt");
    const co = panel.querySelector(".sct-co");
    assert.ok(cp && cpt && co, "the three blocks render");
    assert.equal(cp.nextElementSibling, cpt, "the tendencies dashboard follows the top block");
    assert.equal(cpt.nextElementSibling, co, "career and fantasy close the page");
    assert.equal(panel.querySelector(".sct-cp-flag"), null, "no comparison flag anywhere: the premium designs are the page");
    assert.equal(cp.querySelector(".sct-cp-h2").textContent, "Offensive Coaching & Scheme");
    assert.equal(cp.querySelector(".sct-cp-dek").textContent, "Play-calling tendencies, offensive philosophy, formations, and coaching history.");
    assert.deepEqual([...cp.querySelectorAll(".sct-cp-h3")].map((h) => h.textContent), ["Play Calling", "Formations & Tempo"]);
    assert.deepEqual([...cpt.querySelectorAll(".sct-cpt-h3")].map((h) => h.textContent), ["Formations & Personnel", "Situational Play Calling", "Target & Backfield Tendencies"]);
    // The original header, identity block, tendency tables and sections 3-5 are off the page (unmounted, not deleted).
    for (const sel of [".sct-co-head", ".sct-co-grid.is-overview", ".sct-co-tend", ".sct-co-form", ".sct-co-situational", ".sct-co-targets", ".sct-co-table", ".sct-co-panel", ".sct-co-card"]) {
      assert.equal(panel.querySelector(sel), null, `${sel} is gone`);
    }
    // The premium career block, the season table and fantasy remain, in order, inside .sct-co.
    const order = ["#coaching-career-premium", ".sct-co-dossier", ".sct-co-fantasy"].map((sel) => co.querySelector(sel));
    order.forEach((el, i) => assert.ok(el, `component ${i} present`));
    const all = [...co.querySelectorAll("*")];
    const idx = order.map((el) => all.indexOf(el));
    assert.deepEqual([...idx].sort((a, b) => a - b), idx);
    assert.deepEqual([...co.querySelectorAll(":scope > .sct-co-block > .sct-co-h3")].map((h) => h.textContent), []);
    assert.equal(co.querySelector("#coaching-career-premium .sct-cpt-h3").textContent, "Coaching Career & Historical Performance");
    assert.doesNotMatch(panel.textContent, /Offensive Identity · Through Week/);
    assert.ok(co.querySelector(".sct-co-fantasy .sct-co-bottom"));
    assert.equal(co.querySelector(".sct-co-fantasy").hasAttribute("open"), false);
  });

  test("a section address promotes the premium heading to the page's only H1, in the address's words", async () => {
    const { doc } = await page("/embed/team/buffalo-bills?section=coaching&h1=1");
    const h1s = [...doc.querySelectorAll("h1")];
    assert.equal(h1s.length, 1);
    assert.ok(h1s[0].classList.contains("sct-cp-h2"), "the premium heading is the H1");
    assert.equal(h1s[0].textContent, "Buffalo Bills Offensive Coordinator & Scheme (2026)");
    assert.equal(doc.querySelector("#coaching-premium h2.sct-cp-h2"), null);
  });

  test("the overview: coordinator profile under the head coach, Coaching Continuity, four identity KPIs", async () => {
    const { doc } = await page("/team/new-england-patriots/coaching/");
    const card = doc.querySelector("#coaching-premium .sct-cp-profile");
    assert.equal(card.querySelector(".sct-cp-kicker").textContent, "Offensive Coordinator & Play-Caller");
    assert.equal(card.querySelector(".sct-cp-name").textContent, "Josh McDaniels");
    assert.equal(card.querySelector(".sct-cp-context").textContent, "Under head coach Mike Vrabel · Third stint with New England");
    assert.deepEqual([...card.querySelectorAll(".sct-cp-pill")].map((t) => t.textContent), ["Belichick / Patriots lineage", "Erhardt-Perkins tree"]);
    assert.equal(card.querySelector(".sct-cp-cont-label").textContent, "Coaching Continuity");
    assert.equal(card.querySelector(".sct-cp-cont-status").textContent, "High");
    assert.doesNotMatch(doc.querySelector("#coaching").textContent, /Tendency reliability/);
    // The timeline lives in the premium career block.
    assert.ok(doc.querySelectorAll("#coaching-career-premium .sct-cc-stop").length >= 5);
    const pane = doc.querySelector("#coaching-premium .sct-cp-kpis");
    assert.deepEqual(
      [...pane.querySelectorAll(".sct-cp-kpi-label")].map((l) => l.textContent),
      ["Pass Rate", "Red-Zone Pass Rate", "Pre-Snap Motion", "Neutral Pace"],
    );
    const env = usage.teams.ne.env;
    const values = [...pane.querySelectorAll(".sct-cp-kpi-value")].map((v) => v.textContent);
    assert.equal(values[0], `${env.passRate.value}%`);
    assert.equal(values[3], `${env.pace.value.toFixed(1)}s`);
    // Deltas in percentage points with a neutral triangle, the same unit as the table.
    const lines = [...pane.querySelectorAll(".sct-cp-kpi-move, .sct-cp-kpi-pill")].map((l) => l.textContent);
    for (const l of lines) assert.match(l, /^([▲▼] \d+(\.\d)? pp vs 2025|[▲▼] \d+\.\d+s (faster|slower) than 2025|\d+(st|nd|rd|th) in NFL|Level with 2025)$/, l);
  });

  test("the tenure claim is the official count: 15th season, no 16th (mak, 2026-11-05)", async () => {
    const { doc } = await page("/team/new-england-patriots/coaching/");
    const text = doc.querySelector("#coaching").textContent + doc.querySelector('[data-sct-faq-for="coaching"]').textContent;
    assert.doesNotMatch(text, /16th (Patriots|New England) season/);
    assert.match(text, /15th Patriots season with play-calling responsibility/);
    assert.equal(coaching.teams.ne.reliability.priorSeasonsAsCaller, 14);
  });
});

describe("the tendencies tables", () => {
  test("two groups, Play Calling and Formations & Tempo, each with a key takeaway; fourth down moved out", async () => {
    const { doc } = await page("/team/buffalo-bills/coaching/");
    const groups = [...doc.querySelectorAll("#coaching-premium .sct-cp-section")];
    assert.deepEqual(groups.map((g) => g.querySelector(".sct-cp-h3").textContent), ["Play Calling", "Formations & Tempo"]);
    const labels = (g) => [...g.querySelectorAll("tbody th .sct-co-tlabel")].map((t) => t.textContent);
    assert.deepEqual(labels(groups[0]), ["Pass rate (all downs)", "Pass rate over expected", "Early-down pass rate", "Red-zone pass rate", "Play-action rate"]);
    assert.deepEqual(labels(groups[1]), ["Pre-snap motion", "Shotgun rate", "No-huddle rate", "Neutral pace"]);
    for (const g of groups) {
      const heads = [...g.querySelectorAll("thead th")].map((th) => th.textContent);
      // No NFL avg column: the tick on the dumbbell carries it, with the number on hover.
      assert.deepEqual(heads, ["Metric", "2025Brady", "2026Current", "Changevs 2025 · Tick = NFL Avg"]);
      for (const el of g.querySelectorAll(".sct-cp-change")) {
        assert.match(el.textContent, /^(steady|-|[▲▼] \d+(\.\d)? pp|[▲▼] \d+\.\d+s (faster|slower))$/);
      }
      for (const tick of g.querySelectorAll(".sct-cp-db-avg")) assert.match(tick.getAttribute("title"), /^NFL avg /);
      assert.ok(g.querySelectorAll("tr.is-notable").length <= 1, "at most one gold row per group");
    }
    const take = groups[0].querySelector(".sct-cp-take");
    assert.ok(take.querySelector(".sct-cp-take-h").textContent.endsWith("."));
    assert.match(take.querySelector(".sct-cp-take-b").textContent, /^(Compared with 2025, Buffalo is |No tendency in this group has moved)/);
    assert.doesNotMatch(take.querySelector(".sct-cp-take-b").textContent, / pts\b/);
    assert.doesNotMatch(doc.querySelector("#coaching-premium").textContent, /4th-down go rate/);
    assert.equal(doc.querySelectorAll("#coaching-premium button.sct-co-tlabel[popovertarget]").length, 9);
  });

  test("the feed-backed rows carry the usage file's live numbers, not the spec placeholders", async () => {
    const { doc } = await page("/team/buffalo-bills/coaching/");
    const rows = [...doc.querySelectorAll("table.sct-cp-table tbody tr")];
    const env = usage.teams.buf.env;
    const current = (label) =>
      rows.find((r) => r.querySelector("th").textContent.startsWith(label)).querySelector(".is-now")
        .textContent;
    assert.equal(current("Pass rate (all downs)"), `${env.passRate.value}%`);
    assert.equal(current("Neutral pace"), `${env.pace.value.toFixed(1)}s`);
    assert.equal(current("Red-zone pass rate"), `${env.rzPassRate.value}%`);
    assert.match(current("Pass rate over expected"), /^[+−]/);
  });

  test("formations: shotgun against under center, three KPI cards, and what is not charted", async () => {
    const { doc } = await page("/team/new-england-patriots/coaching/");
    const form = doc.querySelector(".sct-cpt-section.is-formations");
    const sg = coaching.teams.ne.tendencies.rows.find((r) => r.key === "shotgunRate");
    assert.equal(form.querySelector(".sct-cpt-split-stat.is-sg b").textContent, sg.current);
    assert.match(form.querySelector(".sct-cpt-split").getAttribute("aria-label"), new RegExp(`^Shotgun ${sg.current} of snaps, under center`));
    assert.deepEqual([...form.querySelectorAll(".sct-cpt-kpi-label")].map((l) => l.textContent), ["Pre-snap motion", "Play-action rate", "No-huddle rate"]);
    assert.match(form.querySelector(".sct-cpt-note").textContent, /personnel groupings \(11, 12, 21 personnel\)/);
  });

  test("situational: red zone and fourth down carry their samples; the go rate reads N of M", async () => {
    const { doc } = await page("/team/new-england-patriots/coaching/");
    const panel = doc.querySelector(".sct-cpt-card.is-rz");
    const s = coaching.teams.ne.tendencies.samples;
    const sits = [...panel.querySelectorAll(".sct-cpt-metric")];
    assert.deepEqual(sits.map((x) => x.querySelector(".sct-cpt-metric-label").textContent), ["Red-zone pass rate", "Fourth-down go rate"]);
    assert.equal(sits[1].querySelector(".sct-cpt-metric-value").textContent, `${s.fourthShortGo} of ${s.fourthShortAll}`);
    assert.match(sits[0].textContent, new RegExp(`${s.rzPlays} red-zone plays this season`));
    if (s.fourthShortAll < 15) assert.match(sits[1].querySelector(".sct-cpt-caution").textContent, /A small sample: a tendency to watch, not a settled one\./);
    assert.match(panel.querySelector(".sct-cpt-note").textContent, /^Fourth-down decisions are game management, shared with head coach Mike Vrabel/);
    // Beside it, the score-state card.
    const cards = [...doc.querySelectorAll(".sct-cpt-section.is-situational .sct-cpt-card")];
    assert.equal(cards.length, 2);
    assert.match(cards[0].querySelector(".sct-cpt-h4").textContent, /Play-Calling by Score State/);
  });
});

describe("career and fantasy", () => {
  test("the Staff profile strip is gone (mak, 2026-11-02)", async () => {
    const { doc } = await page("/team/buffalo-bills/coaching/");
    assert.equal(doc.querySelector(".sct-co-staff"), null);
    assert.equal(doc.querySelectorAll(".sct-co-staffcard").length, 0);
  });

  test("the current chart stop and history row are the gold ones; finishes live in Fantasy Impact", async () => {
    const { doc } = await page("/team/buffalo-bills/coaching/");
    const block = doc.querySelector(".sct-co-dossier");
    assert.equal(block.querySelectorAll(".sct-co-dstop, .sct-co-idtile").length, 0);
    // The chart is the premium block's: one point per season, the live season ringed in gold.
    const svg = doc.querySelector("#coaching-career-premium .sct-cc-svg.is-wide");
    assert.equal(svg.querySelectorAll(".sct-cc-seg").length, coaching.teams.buf.dossier.length);
    assert.equal(svg.querySelectorAll(".sct-cc-pt.is-current").length, 1);
    const rows = [...block.querySelectorAll("table.sct-co-fptable tbody tr")];
    assert.ok(rows[rows.length - 1].classList.contains("is-current"));
    assert.equal(rows[rows.length - 1].querySelector(".sct-co-fnow").textContent, "In-season");
    assert.equal(block.querySelector("table.sct-co-finishes"), null, "no finishes in the NFL block");
    assert.ok(doc.querySelector(".sct-co-fantasy table.sct-co-finishes"), "finishes in Fantasy Impact");
  });
});

describe("signals and the career block", () => {
  test("every numeric table row carries a dumbbell with prior, now and the NFL tick; a small-sample fourth down is no signal", async () => {
    const { doc } = await page("/team/new-england-patriots/coaching/");
    assert.equal(doc.querySelector(".sct-co-shifts"), null);
    assert.equal(doc.querySelectorAll(".sct-co-verdict").length, 0);
    const all = [...doc.querySelectorAll("table.sct-cp-table tbody tr")];
    const numeric = all.filter((tr) => /\d/.test(tr.querySelector(".is-prior").textContent));
    assert.equal(all.filter((tr) => tr.querySelector(".sct-cp-db")).length, numeric.length);
    for (const tr of numeric) {
      const db = tr.querySelector(".sct-cp-db");
      assert.ok(db.querySelector(".sct-cp-db-prior") && db.querySelector(".sct-cp-db-now"));
      assert.ok(db.querySelector(".sct-cp-db-avg"), "NFL average tick");
    }
    // The bottom line's signal list leaves the three-snap fourth down out.
    const bl = doc.querySelector(".sct-co-bl");
    assert.doesNotMatch(bl.textContent, /4th-down/);
  });

  test("the career block is the season-by-season NFL table alone; heading, timeline and chart are the premium's", async () => {
    const { doc } = await page("/team/new-england-patriots/coaching/");
    const block = doc.querySelector(".sct-co-dossier");
    assert.equal(block.querySelector(".sct-co-h3"), null);
    assert.equal(block.querySelector(".sct-co-path"), null);
    assert.equal(block.querySelector("figure.sct-co-chart"), null);
    assert.equal(block.previousElementSibling.id, "coaching-career-premium");
    const seasons = coaching.teams.ne.dossier.flatMap((r) => r.seasons);
    // The table: every season on a stop, PPG and rank first, shares where tracked.
    assert.match(block.querySelector(".sct-co-fptitle").textContent, /^Season by Season Under McDaniels, 2005-26$/);
    const heads = [...block.querySelectorAll("table.sct-co-fptable thead th")].map((th) => th.textContent);
    assert.deepEqual(heads.slice(0, 4), ["Season", "Team", "Points/G", "NFL rank"]);
    assert.equal(heads.length, 8);
    const all = [...block.querySelectorAll("table.sct-co-fptable tbody tr")];
    const gaps = all.filter((tr) => tr.classList.contains("sct-co-fpgap"));
    assert.deepEqual(gaps.map((tr) => tr.textContent), ["2024 · not calling plays"]);
    const rows = all.filter((tr) => !tr.classList.contains("sct-co-fpgap"));
    assert.equal(rows.length, seasons.length);
    const cells = (tr) => [...tr.children].map((c) => c.textContent);
    assert.deepEqual(cells(rows[0]).slice(0, 4), ["2005not the caller", "NEQB coach2005", "23.7", "-"]);
    assert.deepEqual(cells(rows[2]).slice(0, 3), ["2007", "36.8", "1st"]);
    const r2022 = rows.find((tr) => cells(tr)[0] === "2022");
    assert.deepEqual(cells(r2022), ["2022", "LVHead coach2022-23", "23.2", "12th", "62%+2", "20%+1", "18%↓ 3", "78%"]);
    const live = rows[rows.length - 1];
    assert.deepEqual(cells(live).slice(0, 3), ["2026In-season", "23.0", "16th"]);
    assert.equal(block.querySelectorAll("table.sct-co-fptable tbody tr.is-current").length, 1);
    assert.equal(block.querySelector(".sct-co-fpill"), null, "no finish pills in the NFL table");
    const stats = [...block.querySelectorAll(".sct-co-fpstat")].map((li) => li.textContent);
    assert.equal(stats[0], "80%Peak lead-back share · 2023 LV");
    assert.match(stats[1], /^\d+ \/ 10tracked seasons with (WR|RB|TE) share 3\+ pp (below|above) league$/);
  });

  test("Fantasy Impact: collapsed, with the signal readings, the finishes by season and the bottom line", async () => {
    const { doc } = await page("/team/new-england-patriots/coaching/");
    const fan = doc.querySelector(".sct-co-fantasy");
    assert.equal(fan.tagName, "DETAILS");
    assert.equal(fan.hasAttribute("open"), false);
    assert.match(fan.querySelector("summary").textContent, /^Fantasy Impact/);
    const reads = [...fan.querySelectorAll(".sct-co-fread-h")].map((h) => h.textContent);
    assert.deepEqual(reads, coaching.teams.ne.shifts.filter((s) => s.key !== "fourthGoRate").map((s) => s.heading));
    const fin = fan.querySelector("table.sct-co-finishes");
    const history = coaching.teams.ne.finishes.history.length + 1;
    assert.equal(fin.querySelectorAll("tbody tr").length, history);
    assert.ok(fin.querySelector("tbody tr.is-current .sct-co-fnow"));
    assert.ok(fan.querySelector(".sct-co-bottom .sct-co-bl"));
  });
});

describe("panels", () => {
  test("distribution rows carry league-average markers and the gold lean, with the numbers in text", async () => {
    const { doc } = await page("/team/buffalo-bills/coaching/");
    const panel = doc.querySelector(".sct-cpt-card.is-dist");
    assert.match(panel.querySelector(".sct-cpt-h4").textContent, /^Target Distribution Under Brady$/);
    const rows = coaching.teams.buf.distribution.rows;
    assert.equal(panel.querySelectorAll(".sct-cpt-row").length, rows.length);
    assert.equal(panel.querySelectorAll(".sct-cpt-mark").length, rows.length);
    assert.match(panel.textContent, new RegExp(`${rows[0].pct}%NFL ${rows[0].nfl}%`));
  });

  test("the backfield chart's current bar is live from the usage file, in gold, on a 0-100% scale", async () => {
    const { doc } = await page("/team/buffalo-bills/coaching/");
    const bf = doc.querySelector(".sct-cpt-card.is-back");
    assert.match(bf.querySelector(".sct-cpt-h4").textContent, /^Backfield Share Under Brady$/);
    const cols = [...bf.querySelectorAll(".sct-cpt-col")];
    assert.equal(cols.length, coaching.teams.buf.backfield.bars.length);
    const current = cols[cols.length - 1];
    assert.ok(current.classList.contains("is-current"));
    const lead = Math.round(Math.max(...usage.teams.buf.players.filter((p) => p.pos === "RB").map((p) => p.woppShare ?? 0)));
    assert.equal(current.querySelector(".sct-cpt-col-val").textContent, `${lead}%`);
    assert.equal(current.querySelector(".sct-cpt-col-bar").getAttribute("style"), `height:${lead}%`);
  });

  test("the score-state card reads each row against leading; the bottom line reads the page", async () => {
    const { doc } = await page("/team/buffalo-bills/coaching/");
    const scoreState = doc.querySelector(".sct-cpt-card.is-score");
    assert.match(scoreState.querySelector(".sct-cpt-h4").textContent, /Play-Calling by Score State/);
    const data = coaching.teams.buf.scoreState.rows;
    const rows = [...scoreState.querySelectorAll(".sct-cpt-row")];
    assert.equal(rows.length, data.length);
    const vals = rows.map((r) => r.querySelector(".sct-cpt-row-val").textContent);
    assert.match(vals[0], /^\d+% passBaseline$/);
    for (const r of vals.slice(1)) assert.match(r, /^\d+% pass[+−]?\d+ pp$/, r);
    for (const r of rows) assert.match(r.querySelector(".sct-cpt-row-n").textContent, /^\d+ plays$/);
    assert.match(scoreState.querySelector(".sct-cpt-take-h").textContent, /pass when trailing by 7\+/);
    const bottom = doc.querySelector(".sct-co-bottom");
    const items = [...bottom.querySelectorAll("ul.sct-co-bl li")].map((li) => li.querySelector(".sct-co-bl-k").textContent);
    assert.equal(items[0], "2025 carryover");
    assert.ok(items.includes("Historical leans"));
    assert.match(bottom.querySelector("details.sct-co-more").textContent, /The fantasy bottom line: Brady/);
  });

  test("NE: the deviating position is the only gold bar, with its gap as a pill", async () => {
    const { doc } = await page("/team/new-england-patriots/coaching/");
    const panel = doc.querySelector(".sct-cpt-card.is-dist");
    const rows = coaching.teams.ne.distribution.rows;
    const diffs = [...panel.querySelectorAll(".sct-cpt-badge")].map((d) => d.textContent);
    assert.deepEqual(diffs, rows.map((r) => `${r.pct - r.nfl === 0 ? "0" : `${r.pct - r.nfl > 0 ? "+" : "−"}${Math.abs(r.pct - r.nfl)}`} pp`));
    assert.equal(panel.querySelectorAll(".sct-cpt-fill.is-gold").length, 1);
    assert.ok(doc.querySelector(".sct-cpt-card.is-back .sct-cpt-col.is-current"));
  });
});

describe("FAQ", () => {
  test("the coaching questions are visible in the tail, in the brief's order and count", async () => {
    const { doc } = await page("/team/buffalo-bills/coaching/");
    const tail = doc.querySelector('[data-sct-faq-for="coaching"]');
    assert.ok(tail);
    const qs = [...tail.querySelectorAll(".sct-faq-q")].map((q) => q.textContent);
    assert.ok(qs.length >= 12 && qs.length <= 16, `12-16 questions, got ${qs.length}`);
    assert.equal(qs[0], "Who is the Bills offensive coordinator in 2026?");
    assert.equal(qs[1], "Who calls plays for the Bills offense?");
    assert.ok(qs.some((q) => /^Are the Bills a pass-heavy offense/.test(q)));
    assert.ok(qs.some((q) => /target running backs often/.test(q)));
    assert.ok(qs.some((q) => /mean for fantasy football/.test(q)));
    // No per-question "See the full coaching profile" link any more.
    assert.equal(tail.querySelector(".sct-faq-more"), null);
  });

  test("a returning caller is asked how the offense changed; a new caller what changed", async () => {
    const buf = await page("/team/buffalo-bills/coaching/");
    const bufQs = [...buf.doc.querySelectorAll('[data-sct-faq-for="coaching"] .sct-faq-q')].map((q) => q.textContent);
    assert.ok(bufQs.includes("How has the Bills offense changed in 2026?"));
    assert.ok(bufQs.includes("Is 2025 a useful baseline for predicting the Bills offense in 2026?"));
    const det = await page("/team/detroit-lions/coaching/");
    const detQs = [...det.doc.querySelectorAll('[data-sct-faq-for="coaching"] .sct-faq-q')].map((q) => q.textContent);
    assert.ok(detQs.includes("What changed with the Lions offense in 2026?"));
    const baseline = [...det.doc.querySelectorAll('[data-sct-faq-for="coaching"] .sct-faq-item')].find((d) =>
      /useful baseline/.test(d.querySelector(".sct-faq-q").textContent),
    );
    assert.ok(/^Only with care\./.test(baseline.querySelector(".sct-faq-a").textContent));
  });

  test("the answers quote the tendencies table's own numbers", async () => {
    const { doc } = await page("/team/buffalo-bills/coaching/");
    const tail = doc.querySelector('[data-sct-faq-for="coaching"]');
    const rz = [...tail.querySelectorAll(".sct-faq-item")].find((d) => /pass in the red zone/.test(d.querySelector(".sct-faq-q").textContent));
    assert.ok(rz);
    const m = rz.querySelector(".sct-faq-a").textContent.match(/passed on (\d+(?:\.\d+)?)% of red-zone plays/);
    assert.ok(m, "the red-zone answer quotes a rate");
    const rows = [...doc.querySelectorAll(".sct-cp-table tbody tr")];
    const rzRow = rows.find((r) => /Red-zone pass rate/.test(r.textContent));
    assert.ok(rzRow && rzRow.textContent.includes(`${m[1]}%`), "the same rate the table shows");
  });

  test("…and every question is in the page's FAQPage with the answer the page shows", async () => {
    const { doc, body } = await page("/team/buffalo-bills/coaching/");
    const faq = [...doc.querySelectorAll('script[type="application/ld+json"]')]
      .map((s) => JSON.parse(s.textContent))
      .find((j) => j["@type"] === "FAQPage");
    const tail = doc.querySelector('[data-sct-faq-for="coaching"]');
    const items = [...tail.querySelectorAll(".sct-faq-item")];
    assert.ok(items.length > 0);
    for (const item of items) {
      const q = item.querySelector(".sct-faq-q").textContent;
      const entry = faq.mainEntity.find((x) => x.name === q);
      assert.ok(entry, `"${q}" is in the FAQPage`);
      const visible = [...item.querySelectorAll(".sct-faq-a")].map((p) => p.textContent).join("\n\n");
      assert.equal(entry.acceptedAnswer.text, visible);
      assert.ok(body.includes(item.querySelector(".sct-faq-a").textContent));
    }
  });
});

describe("the premium blocks draw each club's own data", () => {
  test("top block: profile, continuity, four KPIs, two tables, takeaway, formation donut, banner", async () => {
    for (const slug of ["new-england-patriots", "buffalo-bills"]) {
      const { doc } = await page(`/team/${slug}/coaching/`);
      const cp = doc.querySelector("#coaching-premium");
      assert.ok(!cp.querySelector("h1"), "no H1 on the hub-style page");
      assert.ok(cp.querySelector(".sct-cp-profile .sct-cp-name").textContent.length > 3);
      assert.match(cp.querySelector(".sct-cp-cont-status").textContent, /^(High|Medium|Low)$/);
      assert.equal(cp.querySelectorAll(".sct-cp-kpi").length, 4);
      assert.ok(cp.querySelector(".sct-cp-take .sct-cp-take-h").textContent.endsWith("."));
      assert.match(cp.querySelector(".sct-cp-form-title").textContent, /^Formation Profile \(\d{4}\)$/);
      assert.ok(cp.querySelector(".sct-cp-banner .sct-cp-banner-h").textContent.endsWith("."));
      const team = coaching.teams[slug === "new-england-patriots" ? "ne" : "buf"];
      const sg = team.tendencies.rows.find((r) => r.key === "shotgunRate");
      assert.match(cp.querySelector(".sct-cp-donut").getAttribute("aria-label"), new RegExp(`^Shotgun ${sg.current} of snaps, under center`));
      assert.doesNotMatch(cp.querySelector(".sct-cp-form").textContent, /Other/);
      // The table's current column is the row view's current value, row for row.
      const now = [...cp.querySelectorAll(".sct-cp-table td.is-now")].map((td) => td.textContent);
      const prior = [...cp.querySelectorAll(".sct-cp-table td.is-prior")].map((td) => td.textContent);
      assert.equal(now.length, 9);
      assert.equal(prior.length, 9);
      for (const p of prior) assert.match(p, /^(-|[+−]?\d+(\.\d+)?(%|s))$/, p);
    }
  });

  test("the profile and continuity come from each club's own data; no fourth-down headline", async () => {
    const { doc } = await page("/team/detroit-lions/coaching/");
    const cp = doc.querySelector("#coaching-premium");
    assert.equal(cp.querySelector(".sct-cp-cont-status").textContent, "Low");
    assert.match(cp.querySelector(".sct-cp-context").textContent, /First season calling plays for the Lions$/);
    assert.doesNotMatch(cp.textContent, /4th-down go rate|Fourth-down/);
    const ne = await page("/team/new-england-patriots/coaching/");
    const necp = ne.doc.querySelector("#coaching-premium");
    assert.equal(necp.querySelector(".sct-cp-context").textContent, "Under head coach Mike Vrabel · Third stint with New England");
    assert.deepEqual([...necp.querySelectorAll(".sct-cp-kpi-label")].map((l) => l.textContent), ["Pass Rate", "Red-Zone Pass Rate", "Pre-Snap Motion", "Neutral Pace"]);
    assert.match([...necp.querySelectorAll(".sct-cp-kpi-move, .sct-cp-kpi-pill")][3].textContent, /^[▲▼] \d+\.\ds (faster|slower) than 2025$/);
  });

  test("tendencies dashboard: the same models as the retired blocks, bars on a 0-100 scale, takeaways as sentences", async () => {
    for (const slug of ["new-england-patriots", "buffalo-bills"]) {
      const { doc } = await page(`/team/${slug}/coaching/`);
      const cpt = doc.querySelector("#coaching-premium-tendencies");
      const team = coaching.teams[slug === "new-england-patriots" ? "ne" : "buf"];
      const texts = (sel) => [...cpt.querySelectorAll(sel)].map((el) => el.textContent);
      assert.deepEqual(texts(".sct-cpt-h4").slice(0, 2), ["Play-Calling by Score State", "Red Zone and Fourth Down"]);
      const rate = (key) => team.tendencies.rows.find((r) => r.key === key)?.current;
      assert.deepEqual(texts(".sct-cpt-kpi-value"), [rate("motionRate"), rate("paRate"), rate("noHuddleRate")].filter(Boolean));
      for (const line of texts(".sct-cpt-kpi-line")) assert.match(line, /^([−+]\d+(\.\d+)?|0) pp vs NFL avg \d+(\.\d+)?%$/, line);
      for (const fill of cpt.querySelectorAll(".sct-cpt-fill")) assert.match(fill.getAttribute("style"), /^width:\d+(\.\d+)?%$/);
      assert.deepEqual(texts(".is-score .sct-cpt-row-label"), team.scoreState.rows.map((r) => r.label));
      assert.deepEqual(texts(".is-score .sct-cpt-row-n"), team.scoreState.rows.map((r) => r.result.split(" · ")[1]));
      assert.equal(texts(".is-score .sct-cpt-badge")[0], "Baseline");
      assert.deepEqual(texts(".is-dist .sct-cpt-row-label"), team.distribution.rows.map((r) => r.label));
      const values = texts(".sct-cpt-col-val");
      assert.deepEqual([...cpt.querySelectorAll(".sct-cpt-col-bar")].map((b) => b.getAttribute("style")), values.map((v) => `height:${v}`));
      assert.deepEqual(texts(".sct-cpt-col-label"), team.backfield.bars.map((b) => b.label));
      assert.deepEqual(values.slice(0, -1), team.backfield.bars.slice(0, -1).map((b) => `${b.value}%`));
      assert.equal(cpt.querySelectorAll(".sct-cpt-col.is-current").length, 1);
      for (const t of texts(".sct-cpt-take-h")) assert.ok(t.endsWith("."), t);
      assert.equal(cpt.querySelectorAll(".sct-cpt-take").length, 3);
      assert.doesNotMatch(cpt.textContent, /—/);
    }
  });

  test("every club renders the dashboard from its own data, with no Patriots carry-over", async () => {
    const { doc } = await page("/team/arizona-cardinals/coaching/");
    const cpt = doc.querySelector("#coaching-premium-tendencies");
    assert.ok(cpt);
    assert.doesNotMatch(cpt.textContent, /McDaniels|Patriots/);
    assert.equal(cpt.querySelectorAll(".sct-cpt-col").length, coaching.teams.ari.backfield.bars.length);
    assert.match(cpt.querySelector(".is-dist .sct-cpt-h4").textContent, /^Target Distribution Under /);
  });
});

describe("premium career block (mak's brief, 2026-11-05; the design since the same day)", () => {
  test("leads the career section, with the season table and then Fantasy Impact under it, from the same stops", async () => {
    const { doc } = await page("/team/new-england-patriots/coaching/");
    const co = doc.querySelector("#coaching .sct-co");
    const table = co.querySelector(".sct-co-dossier");
    const cc = co.querySelector("#coaching-career-premium.sct-cp.sct-cpt.sct-cc");
    assert.ok(table && cc, "the premium block and the season table render");
    assert.equal(cc.nextElementSibling, table, "the season table sits directly under it");
    assert.ok(table.nextElementSibling.classList.contains("sct-co-fantasy"), "Fantasy Impact follows");
    assert.equal(cc.querySelector(".sct-cp-flag"), null, "no comparison flag: it is the design");
    assert.equal(cc.querySelector(".sct-cpt-h3").textContent, "Coaching Career & Historical Performance");
    assert.equal(cc.querySelector(".sct-cpt-dek").textContent, "McDaniels' stops, and how the offenses he called have scored and distributed the ball.");
    // The timeline: one row per career step, in the stored years; the current stop is the one holding this season.
    const rows = [...cc.querySelectorAll(".sct-cc-stop")];
    const path = coaching.teams.ne.playCaller.careerPath;
    assert.equal(rows.length, path.length);
    assert.deepEqual(rows.map((r) => r.querySelector(".sct-cc-years").textContent), path.map((p) => p.years));
    assert.deepEqual(rows.map((r) => [...r.querySelectorAll(".sct-cc-code")].map((c) => c.textContent).join(" / ")), ["NE", "DEN", "STL", "NE", "LV", "NE"]);
    assert.deepEqual(rows.map((r) => r.querySelector(".sct-cc-role").textContent.replace(" (current stop)", "")), [
      "Assistant, then QB coach; OC & caller from 2006 under Belichick",
      "HC",
      "OC & caller",
      "OC & caller · three Super Bowl wins",
      "HC",
      "OC under Vrabel; 2025 AP Assistant Coach of the Year",
    ]);
    const current = rows.filter((r) => r.classList.contains("is-current"));
    assert.equal(current.length, 1);
    assert.equal(current[0].getAttribute("aria-current"), "step");
    assert.equal(current[0].querySelector(".sct-cc-years").textContent, "2025-26");
    assert.equal(rows.filter((r) => r.querySelector(".sct-cc-crest")).length, rows.length, "every row carries a crest");
    // The chart: a stop per dossier row, a point per season, hollow for the year he did not call, dotted for head-coach stops.
    const svg = cc.querySelector(".sct-cc-svg.is-wide");
    const seasons = coaching.teams.ne.dossier.flatMap((r) => r.seasons);
    assert.equal(svg.querySelectorAll(".sct-cc-pt").length, seasons.length);
    assert.equal(svg.querySelectorAll(".sct-cc-dot.is-hollow").length, 1);
    assert.equal(svg.querySelectorAll(".sct-cc-seg.is-hc").length, 4);
    assert.equal(svg.querySelectorAll(".sct-cc-seg").length, coaching.teams.ne.dossier.length - 1);
    assert.ok(svg.querySelector(".sct-cc-avg"));
    assert.equal(svg.querySelector(".sct-cc-pill.is-avg text").textContent, "NFL AVG");
    // Peak and current are data-driven: the best season he called, and this season's point.
    const peak = Math.max(...coaching.teams.ne.dossier.filter((r) => !/QB coach/.test(r.stop)).flatMap((r) => r.seasons.map((s) => s.ppg)));
    assert.equal(svg.querySelector(".sct-cc-callout.is-peak .v").textContent, peak.toFixed(1));
    const live = coaching.teams.ne.dossier.find((r) => r.current).seasons.at(-1);
    assert.equal(svg.querySelector(".sct-cc-callout.is-current .v").textContent, live.ppg.toFixed(1));
    assert.equal(svg.querySelectorAll(".sct-cc-ring").length, 1);
    assert.equal(svg.querySelectorAll(".sct-cc-dot.is-current").length, 1);
    // Era pills once per run of a club; the year axis ends on the current season; nothing overlaps another label.
    assert.deepEqual([...svg.querySelectorAll(".sct-cc-pill.is-era text")].map((t) => t.textContent), ["NE", "DEN", "STL", "NE", "LV", "NE"]);
    const years = [...svg.querySelectorAll(".sct-cc-year")].map((t) => t.textContent);
    assert.equal(years.at(-1), String(live.year));
    assert.ok(svg.querySelector(".sct-cc-year.is-current"));
    const boxes = [...svg.querySelectorAll(".sct-cc-pill rect, .sct-cc-callout rect")].map((r) => ["x", "y", "width", "height"].map((a) => Number(r.getAttribute(a))));
    for (let i = 0; i < boxes.length; i++) for (let j = i + 1; j < boxes.length; j++) {
      const [ax, ay, aw, ah] = boxes[i]; const [bx, by, bw, bh] = boxes[j];
      assert.ok(!(ax < bx + bw && ax + aw > bx && ay < by + bh && ay + ah > by), `labels ${i} and ${j} overlap`);
    }
    // Legend, note and the hidden table carry the same facts.
    assert.deepEqual([...cc.querySelectorAll(".sct-cc-legend li")].map((li) => li.textContent), ["NE", "DEN", "STL", "LV", "Head coach", "Not the caller", "NFL avg"]);
    assert.equal(cc.querySelector(".sct-cc-note").textContent, "Points per game by season, 2005-2026, one line per stop. The step between stops is the move.");
    assert.equal(cc.querySelectorAll(".sct-cc-chart table.sct-visually-hidden tbody tr").length, seasons.length);
    for (const g of svg.querySelectorAll(".sct-cc-pt")) assert.match(g.getAttribute("aria-label"), /^\d{4}.* · \d+(\.\d)? PPG/);
    assert.ok(cc.querySelector(".sct-cc-svg.is-narrow"), "a narrow chart for the scrolling tiers");
  });

  test("other careers: one stop, a single-club head coach, a many-stop coach", async () => {
    const one = await page("/team/baltimore-ravens/coaching/");
    const cc1 = one.doc.querySelector("#coaching-career-premium");
    assert.equal(cc1.querySelectorAll(".sct-cc-stop").length, coaching.teams.bal.playCaller.careerPath.length);
    assert.equal(cc1.querySelectorAll(".sct-cc-stop.is-current").length, 1);
    assert.doesNotMatch(cc1.textContent, /McDaniels|Patriots/);
    const hc = await page("/team/los-angeles-rams/coaching/");
    const cc2 = hc.doc.querySelector("#coaching-career-premium");
    const svg2 = cc2.querySelector(".sct-cc-svg.is-wide");
    assert.equal(svg2.querySelectorAll(".sct-cc-pt").length, coaching.teams.lar.dossier.flatMap((r) => r.seasons).length);
    assert.deepEqual([...svg2.querySelectorAll(".sct-cc-pill.is-era text")].map((t) => t.textContent), ["LAR"]);
    assert.equal(svg2.querySelector(".sct-cc-seg").classList.contains("is-hc"), true);
    assert.deepEqual([...cc2.querySelectorAll(".sct-cc-legend li")].map((li) => li.textContent), ["LAR", "NFL avg"]);
    const many = await page("/team/pittsburgh-steelers/coaching/");
    const cc3 = many.doc.querySelector("#coaching-career-premium");
    assert.equal(cc3.querySelectorAll(".sct-cc-svg.is-wide .sct-cc-pt").length, coaching.teams.pit.dossier.flatMap((r) => r.seasons).length);
    assert.equal(cc3.querySelectorAll(".sct-cc-svg.is-wide .sct-cc-callout.is-current").length, 1);
  });
});

describe("reliability caveat", () => {
  test("the fourth-down answer states its sample (mak, 2026-11-05)", async () => {
    const { doc } = await page("/team/new-england-patriots/coaching/");
    const s = coaching.teams.ne.tendencies.samples;
    const item = [...doc.querySelectorAll('[data-sct-faq-for="coaching"] .sct-faq-item')].find((d) => /fourth down/.test(d.querySelector(".sct-faq-q").textContent));
    assert.ok(item);
    const a = [...item.querySelectorAll(".sct-faq-a")].map((p) => p.textContent).join(" ");
    assert.match(a, new RegExp(`\\(${s.fourthShortGo} of ${s.fourthShortAll}\\)`));
    if (s.fourthShortAll < 15) assert.match(a, /a small sample that can swing with one decision; fourth-down calls are game management shared with the head coach/);
  });

  test("a HIGH club's Outlook carries no new-play-caller caveat", async () => {
    const { doc } = await page("/team/buffalo-bills/");
    assert.equal(doc.querySelector(".sct-co-caveat"), null);
  });
});

describe("post-refresh check", () => {
  test("the committed coaching data passes the daily team page check", async () => {
    // Offline: the data files alone, against the rules the 2026-10-03 audit
    // set (no overclaims, one period per dossier line, broken tenures not
    // read as unbroken). The network half runs in the daily chain.
    const { spawnSync } = await import("node:child_process");
    const run = spawnSync(process.execPath, [path.join(APP_DIR, "scripts", "team", "checkTeamPages.mjs"), String(coaching.season), "--offline"], {
      encoding: "utf8",
    });
    assert.equal(run.status, 0, run.stdout + run.stderr);
  });
});

